const $=s=>document.querySelector(s),statuses=['已确认','待验证','可能是反编译误差'];let selected='s3',tab='tree',zoom=.85;
const names=[['待机','Idle'],['索敌','Search'],['接近目标','Approach'],['轻攻击','AttackLight'],['重攻击','AttackHeavy'],['举盾防御','Guard'],['后撤','BackStep'],['侧移','Strafe'],['受击硬直','Damage'],['死亡','Dead'],['破防','GuardBreak'],['追击','Chase'],['距离检查','CheckDistance'],['连击衔接','Combo'],['战技准备','SkillReady'],['突刺','Thrust'],['转身','Turn'],['脱战返回','ReturnHome'],['巡逻','Patrol'],['警戒','Alert'],['阶段切换','PhaseChange'],['强化','Buff'],['恢复姿态','Recover'],['终止攻击','Cancel']];
function demo(){return {schemaVersion:1,title:'洛斯里克骑士 · 示例',monsters:['洛斯里克骑士','教宗骑士','无名怪物'],states:names.map((n,i)=>({id:'s'+i,monster:'洛斯里克骑士',name:n[0],originalName:n[1]+'_Demo',raw:'示例占位：请粘贴反编译原文。此处不是游戏实际逻辑。',type:i===12?'判断':'动作',trigger:i===3?'distance <= 3 && targetVisible':'targetVisible',priority:i===9?100:24-i,entry:'alive == true',exit:i===3?'animationEnd == true':'完成当前动作',mutex:i===3?'s4,s5':'',transitions:i===9?'':'s0',parent:i===12?'root':i<8?'s12':'root',relation:'AND',phase:i>19?'第二阶段':'第一阶段',distance:i<6?'近距离':i<16?'中距离':'远距离',status:'待验证',notes:'示例：需要对照反编译 Lua 与战斗录像验证。',x:i===12?380:80+(i%3)*235,y:i===12?180:350+Math.floor(i/3)*150})),log:[]}}
let data;try{data=JSON.parse(localStorage.getItem('ashen-tree-v1'))||demo()}catch{data=demo()}let monster=data.monsters[0];
function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function save(){try{localStorage.setItem('ashen-tree-v1',JSON.stringify(data));$('#saved').textContent='● 已保存至此浏览器'}catch{$('#saved').textContent='存储已满，请导出备份'}}function toast(t){let a=document.createElement('div');a.className='toast';a.textContent=t;document.body.append(a);setTimeout(()=>a.remove(),3000)}function current(){return data.states.find(s=>s.id===selected)}
function visible(){return data.states.filter(s=>s.monster===monster&&(!$('#phase').value||s.phase===$('#phase').value)&&(!$('#distance').value||s.distance===$('#distance').value)&&(!$('#statusFilter').value||s.status===$('#statusFilter').value)&&(!$('#search').value||(s.name+' '+s.originalName).toLowerCase().includes($('#search').value.toLowerCase())))}
function check(){let errors=[];for(let s of data.states){for(let id of [s.parent,...s.transitions.split(',').filter(Boolean),...s.mutex.split(',').filter(Boolean)])if(id!=='root'&&!data.states.some(n=>n.id===id&&n.monster===s.monster))errors.push(s.name+'：引用不存在或跨怪物 '+id);let seen=new Set([s.id]),p=s.parent;while(p&&p!=='root'){if(seen.has(p)){errors.push(s.name+'：行为树父节点存在循环');break}seen.add(p);p=data.states.find(n=>n.id===p)?.parent}if(!s.trigger.trim())errors.push(s.name+'：缺少触发条件')}return [...new Set(errors)]}
function render(){let a=visible();$('#monster').innerHTML=data.monsters.map(x=>`<option ${x===monster?'selected':''}>${esc(x)}</option>`).join('');$('#viewtitle').textContent=monster;$('#count').textContent=a.length;$('#total').textContent=data.states.filter(s=>s.monster===monster).length;$('#confirmed').textContent=data.states.filter(s=>s.monster===monster&&s.status==='已确认').length;$('#pending').textContent=data.states.filter(s=>s.monster===monster&&s.status==='待验证').length;$('#issues').textContent=check().length;$('#list').innerHTML=a.map(s=>`<div class="state ${s.id===selected?'selected':''}" data-id="${esc(s.id)}"><em>${s.status==='已确认'?'●':s.status==='待验证'?'◌':'△'} P${s.priority}</em><strong>${esc(s.name)}</strong><small>${esc(s.originalName)}</small></div>`).join('');$('#list').querySelectorAll('[data-id]').forEach(el=>el.onclick=()=>select(el.dataset.id));renderTree(a);renderTable(a);renderReview();editor()}
function select(id){selected=id;render()}
function renderTree(a){let root={id:'root',name:'战斗主决策',originalName:'Priority Selector',x:380,y:35,type:'选择器',status:'',priority:'↓'};let all=[root,...a];$('#nodes').innerHTML=all.map(s=>`<div class="node ${s.id==='root'?'root':''} ${s.id===selected?'selected':''}" data-id="${esc(s.id)}" style="left:${s.x}px;top:${s.y}px"><strong>${s.type==='判断'?'◇':s.id==='root'?'♧':'▸'} ${esc(s.name)}</strong><small>${esc(s.originalName)}</small><div class="meta">${s.id==='root'?'优先选择 / 从高到低':esc(s.status)+' · P'+s.priority}</div><div class="port"></div></div>`).join('');$('#lines').innerHTML=a.map(s=>{let p=all.find(n=>n.id===s.parent);return p?`<path d="M${p.x+90} ${p.y+94} C${p.x+90} ${p.y+130},${s.x+90} ${s.y-40},${s.x+90} ${s.y}" fill="none" stroke="#69755b" stroke-width="1.5"/>`:''}).join('');$('#nodes').querySelectorAll('.node:not(.root)').forEach(el=>{el.onpointerdown=e=>{let s=data.states.find(n=>n.id===el.dataset.id),sx=e.clientX,sy=e.clientY,ox=s.x,oy=s.y,moved=false;el.setPointerCapture(e.pointerId);el.onpointermove=ev=>{if(Math.abs(ev.clientX-sx)+Math.abs(ev.clientY-sy)>4)moved=true;if(moved){s.x=Math.max(0,ox+(ev.clientX-sx)/zoom);s.y=Math.max(0,oy+(ev.clientY-sy)/zoom);el.style.left=s.x+'px';el.style.top=s.y+'px'}};el.onpointerup=()=>{el.onpointermove=null;save();if(!moved)selected=s.id;render()}}});setZoom()}
function setZoom(){zoom=Math.max(.3,Math.min(1.5,zoom));$('#tree').style.transform=`scale(${zoom})`;$('#scale').textContent=Math.round(zoom*100)+'%'}
function renderTable(a){$('#table').innerHTML='<table><thead><tr>'+['状态 / 原名','优先级','触发条件','阶段 / 距离','验证状态'].map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+a.map(s=>`<tr data-id="${esc(s.id)}"><td>${esc(s.name)}<p>${esc(s.originalName)}</p></td><td>${s.priority}</td><td>${esc(s.trigger)}</td><td>${esc(s.phase)} / ${esc(s.distance)}</td><td>${esc(s.status)}</td></tr>`).join('')+'</tbody></table>';$('#table').querySelectorAll('tr[data-id]').forEach(el=>el.onclick=()=>select(el.dataset.id))}
function renderReview(){$('#review').innerHTML=`<div class="review-card"><b>逻辑完整性检查 · ${check().length} 项</b><p>${check().map(esc).join('<br>')||'父子关系、跨怪物引用、转移引用和触发条件检查通过。状态转移可以成环；行为树父子关系不能成环。'}</p></div><div class="review-card"><b>验证记录</b><p>先记录证据，再将状态标记为已确认。示例条件采用安全的声明式比较语法；自由文本条件需要人工验证。</p></div>`+data.log.slice().reverse().map(l=>`<div class="review-card"><b>${esc(l.at)} · ${esc(l.name)}</b><p>${esc(l.text)}</p></div>`).join('')}
const fields=[['name','中文名称'],['originalName','原始状态名称'],['trigger','触发条件'],['entry','进入条件'],['exit','退出条件'],['mutex','互斥状态 ID（逗号分隔）'],['transitions','状态转移 ID（逗号分隔）'],['raw','原始反编译片段（独立保留）'],['notes','验证证据 / 复盘备注']];
function opts(values,v){return values.map(x=>`<option ${x===v?'selected':''}>${esc(x)}</option>`).join('')}
function editor(){let s=current();if(!s){$('#editor').innerHTML='<p>选择或新增一个状态。</p>';return}$('#editor').innerHTML=`<span class="badge">${esc(s.id)} · ${esc(s.status)}</span><p class="hint">${esc(s.monster)} / 原始资料与重构规则</p><form id="form">`+fields.map(([k,l])=>`<label>${l}</label>${['name','originalName','mutex','transitions'].includes(k)?`<input name="${k}" value="${esc(s[k])}" required>`:`<textarea name="${k}">${esc(s[k])}</textarea>`}`).join('')+`<div class="pair"><div><label>优先级（高者优先）</label><input type="number" name="priority" value="${s.priority}" required></div><div><label>节点类型</label><select name="type">${opts(['动作','判断','选择器','顺序器'],s.type)}</select></div></div><label>父节点 / 判断关系</label><select name="parent"><option value="root">root · 主决策</option>${data.states.filter(n=>n.monster===s.monster&&n.id!==s.id).map(n=>`<option value="${esc(n.id)}" ${s.parent===n.id?'selected':''}>${esc(n.id+' · '+n.name)}</option>`).join('')}</select><label>进入与触发组合</label><select name="relation">${opts(['AND','OR'],s.relation)}</select><div class="pair"><div><label>战斗阶段</label><select name="phase">${opts(['第一阶段','第二阶段'],s.phase)}</select></div><div><label>目标距离</label><select name="distance">${opts(['近距离','中距离','远距离'],s.distance)}</select></div></div><label>验证状态</label><select name="status">${opts(statuses,s.status)}</select><button class="gold" type="submit">保存状态与关系</button><button type="button" id="delete" style="margin-top:10px;width:100%">删除此状态</button></form>`;$('#form').onsubmit=e=>{e.preventDefault();let old=structuredClone(s),v=Object.fromEntries(new FormData(e.target));v.priority=Number(v.priority);v.mutex=v.mutex.replace(/\s/g,'');v.transitions=v.transitions.replace(/\s/g,'');Object.assign(s,v);let issues=check();if(issues.some(x=>x.startsWith(s.name+'：'))){Object.assign(s,old);toast('保存失败：检查循环或无效 ID 引用');return}data.log.push({at:new Date().toLocaleString('zh-CN'),name:s.name,text:s.status+' · '+s.notes});save();render();toast('状态与关系已保存')};$('#delete').onclick=()=>{if(!confirm('删除此状态并清理指向它的关系？'))return;data.states=data.states.filter(n=>n.id!==s.id);data.states.forEach(n=>{if(n.parent===s.id)n.parent='root';for(let k of ['mutex','transitions'])n[k]=n[k].split(',').filter(id=>id!==s.id).join(',')});selected=data.states[0]?.id;save();render()};$('#form [name=mutex]').required=false;$('#form [name=transitions]').required=false}
function download(name,text,type){let u=URL.createObjectURL(new Blob(['\ufeff'+text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}function modal(html){$('#dialogContent').innerHTML=html;$('#dialog').showModal()}$('#close').onclick=()=>$('#dialog').close();
$('#export').onclick=()=>{modal('<h2>导出研究档案</h2><p>导出全部怪物、原始状态与编辑后的关系。SVG 使用当前筛选图。</p><button id="jsonout">完整 JSON / 备份</button><button id="csvout">状态表 CSV</button><button id="svgout">行为树 SVG</button><button id="mdout">交给 Codex 的说明</button>');$('#jsonout').onclick=()=>download('ashen-tree.json',JSON.stringify(data,null,2),'application/json');$('#csvout').onclick=()=>{let keys=['id','monster','name','originalName','trigger','priority','entry','exit','mutex','transitions','parent','relation','phase','distance','status','raw','notes'];download('状态表.csv',[keys,...data.states.map(s=>keys.map(k=>s[k]))].map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv')};$('#mdout').onclick=()=>download('Codex-行为树说明.md','# 行为树重构说明\n\n本档案包含用户原始反编译资料与人工重构关系。示例不是 DS3 实际结论。\n\n目标：实现 Unreal Engine AI / GAS 或 Lua 行为树。保留 originalName 和 raw；不得将待验证内容当作已证实事实。\n\n执行约定：父节点 root 为优先选择器，priority 降序，同优先级按 id 排序。选择器选首个成功子节点；顺序器依次执行且遇失败停止。relation 组合 trigger 与 entry；互斥为双向约束；exit 成立后根据 transitions 转移。动作异步完成与中断、GAS GameplayTag / Ability、Lua 回调需由实现层补充。自由文本和未确认条件应保留为待实现断言。请输出实现与验证用例，不擅自补全游戏事实。\n\n```json\n'+JSON.stringify(data,null,2)+'\n```','text/markdown');$('#svgout').onclick=()=>{let a=visible(),w=Math.max(850,...a.map(s=>s.x+220)),h=Math.max(300,...a.map(s=>s.y+125));let texts=[{x:380,y:35,name:'战斗主决策',originalName:'Priority Selector'},...a].map(s=>`<g><rect x="${s.x}" y="${s.y}" width="181" height="94" rx="6" fill="#202a21" stroke="#a99a77"/><text x="${s.x+12}" y="${s.y+28}" fill="#e5e6dc" font-size="13">${esc(s.name)}</text><text x="${s.x+12}" y="${s.y+55}" fill="#bba777" font-size="10">${esc(s.originalName)}</text></g>`).join('');download('行为树.svg',`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}"><rect width="100%" height="100%" fill="#121914"/>${$('#lines').innerHTML}${texts}</svg>`,'image/svg+xml')}};
$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{try{let d=JSON.parse(await e.target.files[0].text());if(d.schemaVersion!==1||!Array.isArray(d.states)||!Array.isArray(d.monsters)||!d.monsters.length||d.states.length>2000)throw Error('需要 schemaVersion:1、monsters 和 states 数组（最多 2000 个状态）。先导出示例 JSON 获取字段模板。');let ids=new Set();for(let s of d.states){if(!s.id||s.id==='root'||ids.has(s.id))throw Error('状态 ID 必须唯一且不能为 root');ids.add(s.id);for(let k of ['monster','name','originalName','trigger','entry','exit','mutex','transitions','parent','relation','phase','distance','status','raw','notes','type'])if(typeof s[k]!=='string')throw Error('缺少字符串字段：'+k);if(!d.monsters.includes(s.monster)||!Number.isFinite(s.priority)||!Number.isFinite(s.x)||!Number.isFinite(s.y))throw Error('怪物、优先级或坐标无效')}if(!confirm('导入将替换当前档案。请先导出备份，是否继续？'))return;data={...d,log:Array.isArray(d.log)?d.log:[]};monster=d.monsters[0];selected=d.states[0]?.id;save();render();toast('导入完成，请查看逻辑检查')}catch(err){toast('导入失败：'+err.message)}e.target.value=''};
$('#add').onclick=()=>{let s={...demo().states[0],id:'s'+Date.now(),name:'新状态',originalName:'NewState',monster,raw:'',notes:'',parent:'root',x:80,y:180};data.states.push(s);selected=s.id;save();render()};$('#monster').onchange=e=>{monster=e.target.value;selected=data.states.find(s=>s.monster===monster)?.id;render()};['search','phase','distance','statusFilter'].forEach(id=>$('#'+id).oninput=render);document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{tab=el.dataset.tab;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b===el));$('#workspace').hidden=tab!=='tree';$('#table').hidden=tab!=='table';$('#review').hidden=tab!=='review'});$('#plus').onclick=()=>{zoom+=.1;setZoom()};$('#minus').onclick=()=>{zoom-=.1;setZoom()};$('#reset').onclick=()=>{zoom=.85;$('#workspace').scrollTop=0;setZoom()};$('#workspace').onwheel=e=>{e.preventDefault();zoom+=e.deltaY>0?-.05:.05;setZoom()};$('#layout').onclick=()=>{let level=(s,seen=new Set())=>{if(s.parent==='root'||seen.has(s.id))return 0;seen.add(s.id);let p=data.states.find(n=>n.id===s.parent);return p?1+level(p,seen):0};let rows={};data.states.filter(s=>s.monster===monster).forEach(s=>{let d=level(s),i=rows[d]||0;rows[d]=i+1;s.x=40+(i%5)*220;s.y=180+d*360+Math.floor(i/5)*125});save();render()};
function evaluate(expr,ctx){let parts=expr.split(/\s*&&\s*/);return parts.every(p=>{let m=p.trim().match(/^(distance|hp|targetVisible|alive|animationEnd)\s*(==|!=|<=|>=|<|>)\s*(true|false|-?\d+(?:\.\d+)?)$/);if(!m)throw Error('待人工实现条件：'+p);let a=ctx[m[1]],b=m[3]==='true'?true:m[3]==='false'?false:Number(m[3]);return ({'==':()=>a===b,'!=':()=>a!==b,'<=':()=>a<=b,'>=':()=>a>=b,'<':()=>a<b,'>':()=>a>b})[m[2]]()})}
$('#simulate').onclick=()=>{modal('<h2>执行推演 · 单次决策</h2><p>仅推演当前筛选结果。支持 distance / hp / targetVisible / alive / animationEnd 比较及 &&。未知条件返回待验证。</p><label>距离（米）<input id="simDist" type="number" value="2"></label><label>HP（0–100）<input id="simHp" type="number" min="0" max="100" value="100"></label><label><input id="simVisible" type="checkbox" checked style="width:auto"> 目标可见</label><button id="run">运行决策</button><div id="result"></div>');$('#run').onclick=()=>{let ctx={distance:Number($('#simDist').value),hp:Number($('#simHp').value),targetVisible:$('#simVisible').checked,alive:Number($('#simHp').value)>0,animationEnd:false},pool=visible(),traces=[],active=new Set();function visit(s,seen=new Set()){if(seen.has(s.id)){traces.push(s.name+'：循环，停止');return false}seen=new Set(seen).add(s.id);try{let t=evaluate(s.trigger,ctx),en=evaluate(s.entry,ctx);if(!(s.relation==='OR'?t||en:t&&en)){traces.push(s.name+'：条件未满足');return false}if(pool.some(n=>active.has(n.id)&&(s.mutex.split(',').includes(n.id)||n.mutex.split(',').includes(s.id)))){traces.push(s.name+'：互斥阻止');return false}let children=pool.filter(n=>n.parent===s.id).sort((a,b)=>b.priority-a.priority||a.id.localeCompare(b.id));if(children.length){let ok=s.type==='顺序器'?children.every(c=>visit(c,seen)):children.some(c=>visit(c,seen));traces.push(s.name+'：'+(ok?'成功':'失败'));return ok}active.add(s.id);traces.push(s.name+'：进入（动作执行与退出需运行时回调）');return true}catch(e){traces.push(s.name+'：'+e.message);return false}}let roots=pool.filter(s=>s.parent==='root').sort((a,b)=>b.priority-a.priority||a.id.localeCompare(b.id));let success=roots.some(s=>visit(s));$('#result').innerHTML='<p>'+[success?'找到可执行路径':'没有可确认的执行路径',...traces].map(esc).join('<br>')+'</p>';data.log.push({at:new Date().toLocaleString('zh-CN'),name:'决策推演',text:JSON.stringify(ctx)+'\n'+traces.join('\n')});save();renderReview()}};
let panX=0,panY=0;const originalZoom=setZoom;setZoom=function(){originalZoom();$('#tree').style.transform=`translate(${panX}px,${panY}px) scale(${zoom})`};$('#workspace').onpointerdown=e=>{if(e.target.closest('.node,button'))return;let px=panX,py=panY,x=e.clientX,y=e.clientY;$('#workspace').setPointerCapture(e.pointerId);$('#workspace').onpointermove=v=>{panX=px+v.clientX-x;panY=py+v.clientY-y;setZoom()};$('#workspace').onpointerup=()=>$('#workspace').onpointermove=null};$('#reset').onclick=()=>{panX=panY=0;zoom=.85;setZoom()};
render();
